mapper.select:
SELECT

  FROM batch.config_sync_log
 WHERE tenant_id = #{tenantId}
 ORDER BY id DESC
 LIMIT #{limit} OFFSET #{offset}

SELECT

  FROM batch.config_sync_log
 WHERE tenant_id = #{tenantId}
   AND id = #{logId}
 FOR UPDATE

SELECT

  FROM batch.config_sync_log
 WHERE tenant_id = #{tenantId}
   AND sync_direction = 'IMPORT'
   AND detail_json->>'requestKeyHash' = #{requestKeyHash}

SELECT id
  FROM batch.config_sync_log
 WHERE tenant_id = #{tenantId}
   AND sync_direction = 'IMPORT'
   AND detail_json->>'requestKeyHash' = #{requestKeyHash}

SELECT count(1)
  FROM batch.config_sync_log
 WHERE tenant_id = #{tenantId}
